#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-or-later
set -eu
[ "$#" -eq 1 ] || exit 2
src=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
mkdir -p -- "$(dirname -- "$1")"
"${CXX:-m68k-amigaos-g++}" -m68040 -m68881 -std=c++17 -O2 -Wall -Wextra -Werror -fno-exceptions -fno-rtti -fno-builtin -fno-tree-loop-distribute-patterns \
"$src/rules_text.cpp" "$src/original_map.cpp" "$src/original_game.cpp" "$src/original_faction.cpp" "$src/original_world.cpp" "$src/prototype.cpp" "$src/movement.cpp" "$src/saved_speed.cpp" "$src/world_unit_stats.cpp" "$src/combat_prototype.cpp" "$src/world_combat_prototype.cpp" "$src/native_combat_morale.cpp" "$src/world_native_combat_morale.cpp" "$src/basic_combat.cpp" "$src/world_basic_combat.cpp" "$src/fungus_combat.cpp" "$src/world_fungus_combat.cpp" "$src/combat_factions.cpp" "$src/world_combat_factions.cpp" "$src/terrain_defense.cpp" "$src/world_terrain_defense.cpp" "$src/ground_modifiers.cpp" "$src/world_ground_modifiers.cpp" "$src/base_combat.cpp" "$src/world_base_combat.cpp" "$src/sensor_combat.cpp" "$src/world_sensor_combat.cpp" "$src/air_port_combat.cpp" "$src/world_air_port_combat.cpp" "$src/defense_abilities.cpp" "$src/world_defense_abilities.cpp" "$src/land_combat.cpp" "$src/vehicle_stack.cpp" "$src/combat_round.cpp" "$src/retreat_init.cpp" "$src/world_retreat_init.cpp" "$src/world_zoc.cpp" "$src/supply_pods.cpp" "$src/retreat_destination.cpp" "$src/land_engagement.cpp" "$src/vehicle_removal.cpp" "$src/world_vehicle_removal.cpp" "$src/world_casualty.cpp" "$src/artifact_capture.cpp" "$src/land_resolution.cpp" "$src/battle_bookkeeping.cpp" "$src/world_battle_bookkeeping.cpp" "$src/battle_aftermath.cpp" "$src/battle_aftermath_probe.cpp" -o "$1"
